const SENTINELA = "###BRAVO_META###";

return $input.all().map((item) => {
  const raw = String(item.json.output ?? "");
  const i = raw.indexOf(SENTINELA);

  // O corte é no sentinela, não no parse do JSON: JSON malformado
  // custa telemetria, nunca a mensagem do cliente.
  const mensagem = (i === -1 ? raw : raw.slice(0, i)).trim();

  let meta = {};
  if (i !== -1) {
    try {
      meta = JSON.parse(raw.slice(i + SENTINELA.length).trim());
    } catch (e) { /* segue com meta vazio */ }
  }

  return { json: {
    ...item.json,
    output: mensagem,
    close_conversation: meta.close_conversation === true,
    meta,
    _parse_ok: i !== -1 && Object.keys(meta).length > 0,
  }};
});

// ============================================================
// n8n Code Node — pós-Webhook: roteamento por horário (Brasil / SP)
// Modo: "Run Once for All Items"
//
// Janelas CONTÍGUAS (sem buraco, sem sobreposição), em dia útil:
//   humano -> 09:00 até 18:59:59
//   bot    -> 19:00 até 08:59:59 do dia seguinte
// Fim de semana, feriado e ponto facultativo: bot o dia todo.
//
// O corte é um ponto único (CORTE_NOITE). Mexer nele move as duas janelas
// juntas, então nunca sobra minuto órfão.
// ============================================================

// ---------- CONFIGURAÇÃO ----------
const TZ = "America/Sao_Paulo";

// Pontos de corte em minutos desde a meia-noite.
// Humano atende em [CORTE_MANHA, CORTE_NOITE). Bot atende no complemento.
const CORTE_MANHA = 9 * 60;    // 09:00 -> humano assume
const CORTE_NOITE = 19 * 60;   // 19:00 -> bot assume (use 19*60+1 para 19:01 literal)

// Carnaval, Quarta de Cinzas e Corpus Christi: ponto facultativo, não feriado legal.
// true = sem operação humana (bot o dia todo)
const FACULTATIVO_BLOQUEIA = true;

// Feriados fixos: nacionais + São Paulo (municipal/estadual). Formato MM-DD.
const FIXOS = {
  "01-01": "Confraternização Universal",
  "01-25": "Aniversário de São Paulo",
  "04-21": "Tiradentes",
  "05-01": "Dia do Trabalho",
  "07-09": "Revolução Constitucionalista (SP)",
  "09-07": "Independência",
  "10-12": "Nossa Senhora Aparecida",
  "11-02": "Finados",
  "11-15": "Proclamação da República",
  "11-20": "Consciência Negra",
  "12-25": "Natal",
};

// Decretos, emendas de ponte, paradas internas. Formato YYYY-MM-DD.
const OVERRIDES = {
  // "2026-06-05": "Emenda de ponte Corpus Christi",
};

// ---------- FERIADOS MÓVEIS (derivados da Páscoa, sem manutenção anual) ----------
function domingoDePascoa(ano) {
  const a = ano % 19, b = Math.floor(ano / 100), c = ano % 100;
  const d = Math.floor(b / 4), e = b % 4;
  const f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4), k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const mes = Math.floor((h + l - 7 * m + 114) / 31);
  const dia = ((h + l - 7 * m + 114) % 31) + 1;
  return Date.UTC(ano, mes - 1, dia);
}

const DIA = 86400000;
const iso = (ms) => new Date(ms).toISOString().slice(0, 10);

function calendario(ano) {
  const p = domingoDePascoa(ano);
  const feriados = {};
  const facultativos = {};
  for (const [md, nome] of Object.entries(FIXOS)) feriados[`${ano}-${md}`] = nome;
  feriados[iso(p - 2 * DIA)] = "Sexta-feira Santa";
  facultativos[iso(p - 48 * DIA)] = "Carnaval (segunda)";
  facultativos[iso(p - 47 * DIA)] = "Carnaval (terça)";
  facultativos[iso(p - 46 * DIA)] = "Quarta-feira de Cinzas";
  facultativos[iso(p + 60 * DIA)] = "Corpus Christi";
  return { feriados, facultativos };
}

// Classifica um dia: tem ou não operação humana
function statusDoDia(dt) {
  const d = dt.toFormat("yyyy-MM-dd");
  const { feriados, facultativos } = calendario(dt.year);
  const isWeekend = dt.weekday === 6 || dt.weekday === 7;
  const nomeFeriado = OVERRIDES[d] || feriados[d] || null;
  const nomeFacult = facultativos[d] || null;
  const semOperacao =
    isWeekend || Boolean(nomeFeriado) || (FACULTATIVO_BLOQUEIA && Boolean(nomeFacult));
  return { isWeekend, nomeFeriado, nomeFacult, semOperacao };
}

// Próximo dia com operação humana. Vai como contexto para o Agent —
// o LLM está proibido de calcular data.
function proximoDiaUtil(dt) {
  let cur = dt;
  for (let i = 0; i < 30; i++) {
    cur = cur.plus({ days: 1 });
    if (!statusDoDia(cur).semOperacao) return cur;
  }
  return null;
}

// ---------- AVALIAÇÃO ----------
const now = DateTime.now().setZone(TZ);
const minutos = now.hour * 60 + now.minute;
const dia = statusDoDia(now);

const hhmm = (min) =>
  `${String(Math.floor(min / 60)).padStart(2, "0")}:${String(min % 60).padStart(2, "0")}`;

let destino, motivo;
if (dia.semOperacao) {
  destino = "bot";
  motivo = dia.isWeekend
    ? "fim de semana"
    : dia.nomeFeriado
      ? `feriado: ${dia.nomeFeriado}`
      : `ponto facultativo: ${dia.nomeFacult}`;
} else if (minutos >= CORTE_MANHA && minutos < CORTE_NOITE) {
  destino = "humano";
  motivo = null;
} else {
  destino = "bot";
  motivo = `fora do expediente (${hhmm(CORTE_MANHA)}–${hhmm(CORTE_NOITE)})`;
}

const pdu = proximoDiaUtil(now);

const _horario = {
  destino,                               // "humano" | "bot"
  motivo,
  isBusinessTime: destino === "humano",  // alias de compatibilidade
  agora: now.toFormat("yyyy-MM-dd HH:mm"),
  hora: now.hour,
  minuto: now.minute,
  diaSemana: now.weekday % 7,            // 0=dom .. 6=sáb
  isWeekend: dia.isWeekend,
  isHoliday: Boolean(dia.nomeFeriado),
  nomeFeriado: dia.nomeFeriado,
  isFacultativo: Boolean(dia.nomeFacult),
  nomeFacultativo: dia.nomeFacult,
  // contexto injetado no Agent
  proximo_dia_util: pdu ? pdu.toFormat("yyyy-MM-dd") : null,
  proximo_dia_util_nome: pdu ? pdu.setLocale("pt-BR").toFormat("cccc") : null,

  // GANCHO DE HANDOFF: sem a folga de 1h, o bot pode entrar em cima de uma
  // conversa humana em andamento às 19:00. Preencha este campo num nó
  // anterior (consulta ao CRM: houve mensagem de operador nos últimos 30min?)
  // e, se true, force destino "humano" no Switch mesmo fora do expediente.
  conversa_humana_ativa: null,
};

return $input.all().map((item) => ({
  json: { ...item.json, _horario },
}));

// Rama FALSE: horario NO hábil. No hacer nada y devolver la respuesta del webhook.
// El webhook ya respondió 200 (responseMode onReceived), así que aquí simplemente no se continúa.
return []

// ============================================================
// n8n Code Node — preparação de contexto para o Agent  (v2)
// Posição: DEPOIS do Edit/Set que trouxe os dados, ANTES do Agent
// Modo: "Run Once for All Items"
//
// Por que existe: dinheiro, data e nome próprio NÃO podem ser formatados
// pelo LLM — ele formata diferente a cada execução. Aqui tudo chega pronto
// e o prompt só ecoa string.
//
// MUDANÇAS DA v1:
//   1. contexto_agente.sessao_id  -> chave de deduplicação da planilha
//   2. dia_pagamento_txt agora é "no dia 25" (o dia varia mês a mês;
//      "todo dia 25" afirmava uma regra permanente que não existe)
//   3. executivo_email preservado cru (a planilha pede e-mail, não nome)
//   4. bloco sheet_sessao: campos prontos para o node Google Sheets,
//      sem precisar montar expressão coluna a coluna
// ============================================================

const TZ = "America/Sao_Paulo";

// "R$446.84 BRL" | "1.446,84" | 446.84  ->  446.84 (number) | null
function parseValor(v) {
  if (v === null || v === undefined || v === "") return null;
  if (typeof v === "number") return isFinite(v) ? v : null;

  let s = String(v).replace(/[^\d.,-]/g, "").trim();
  if (s === "") return null;

  const ultPonto = s.lastIndexOf(".");
  const ultVirg = s.lastIndexOf(",");

  if (ultPonto !== -1 && ultVirg !== -1) {
    // o separador mais à direita é o decimal
    if (ultVirg > ultPonto) s = s.replace(/\./g, "").replace(",", ".");
    else s = s.replace(/,/g, "");
  } else if (ultVirg !== -1) {
    // só vírgula: decimal se tiver 1-2 dígitos depois, senão é milhar
    s = s.length - ultVirg - 1 <= 2 ? s.replace(",", ".") : s.replace(/,/g, "");
  }

  const n = parseFloat(s);
  return isFinite(n) ? n : null;
}

function formatarBRL(n) {
  if (n === null) return null;
  return "R$ " + n.toFixed(2).replace(".", ",").replace(/\B(?=(\d{3})+(?!\d))/g, ".");
}

function capitalizar(s) {
  if (!s) return null;
  const t = String(s).trim();
  if (t === "") return null;
  return t
    .split(/\s+/)
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1).toLowerCase())
    .join(" ");
}

// "2026-09-15" + "terça-feira" -> "terça-feira (15/09)"
function formatarDiaUtil(iso, nome) {
  if (!iso) return nome || null;
  const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const curto = m ? `${m[3]}/${m[2]}` : null;
  if (nome && curto) return `${nome} (${curto})`;
  return nome || curto;
}

// timestamp ordenável, fuso São Paulo -> "2026-09-15 20:14"
function agoraSP() {
  const p = new Intl.DateTimeFormat("sv-SE", {
    timeZone: TZ,
    year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", hour12: false,
  }).format(new Date());
  return p.replace("T", " ");
}

// 5511946594177 -> (11) 94659-4177
function telefoneFmt(t) {
  const d = String(t || "").replace(/\D/g, "");
  const n = d.startsWith("55") ? d.slice(2) : d;
  if (n.length === 11) return `(${n.slice(0, 2)}) ${n.slice(2, 7)}-${n.slice(7)}`;
  if (n.length === 10) return `(${n.slice(0, 2)}) ${n.slice(2, 6)}-${n.slice(6)}`;
  return t || null;
}

return $input.all().map((item) => {
  const j = item.json || {};
  const h = j._horario || {};
  const body = j.body || {};

  const valorNum = parseValor(j.monthly_payment);
  const dia = Number(j.data_pagamento);
  const diaValido = Number.isInteger(dia) && dia >= 1 && dia <= 31;

  const executivo = capitalizar(j.executivo_sc);
  const executivoEmail = (j.esc || j.executivo_email || "").trim() || null;
  const primeiroNome = capitalizar(String(j.names || "").split(/\s+/)[0]);

  const status = (j.status_programa || "").toLowerCase();
  const programaAtivo = status === "active";
  const clienteIdentificado = Boolean(j.bank_reference);

  // Só libera falar de pagamento com programa ativo E dado presente.
  // Programa pausado/cancelado -> o valor em cadastro pode não valer mais.
  const podeFalarPagamento = programaAtivo && valorNum !== null;

  // ---------- CHAVE DE SESSÃO ----------
  // "tracker|dia-util" = um registro por cliente por dia útil de retorno.
  // Sexta 20h, sábado, domingo e segunda 7h caem todos em "segunda-feira",
  // então a planilha guarda UMA linha por cliente, não uma por mensagem.
  // Fallbacks existem para que a chave nunca seja "undefined|undefined":
  // sem tracker a linha ainda é rastreável pelo telefone.
  const trackerKey = body.tracker_id || `fone_${String(body.user || "").replace(/\D/g, "")}` || "sem_id";
  const diaKey = h.proximo_dia_util || "sem_data";
  const sessaoId = `${trackerKey}|${diaKey}`;

  const ctx = {
    // chave de deduplicação
    sessao_id: sessaoId,

    // identidade
    cliente_identificado: clienteIdentificado,
    primeiro_nome: primeiroNome,                    // "Regina" | null
    numero_programa: j.bank_reference || null,
    status_programa: j.status_programa || null,

    // executivo
    tem_executivo: Boolean(executivo),
    executivo: executivo,                           // "Gabriela" | null

    // retorno
    proximo_dia_util_txt: formatarDiaUtil(h.proximo_dia_util, h.proximo_dia_util_nome),

    // pagamento — strings JÁ FORMATADAS, o Agent só ecoa
    pode_falar_pagamento: podeFalarPagamento,
    valor_mensal_txt: podeFalarPagamento ? formatarBRL(valorNum) : null,
    dia_pagamento_txt: podeFalarPagamento && diaValido ? `no dia ${dia}` : null,

    // link fixo de pagamento
    link_pagamento: "https://gobravo.trytoku.com/landing",
  };

  return {
    json: {
      ...j,
      contexto_agente: ctx,

      // ---------- pronto para o node Google Sheets ----------
      // Aba "sessoes" · Append or Update Row · coluna-chave: sessao_id
      // NÃO mapeie a coluna notificado_em aqui: ela é escrita só pelo job
      // agendado, e o Sheets preserva as colunas que você não mapeia.
      sheet_sessao: {
        sessao_id: sessaoId,
        tracker_id: body.tracker_id || null,
        nome: primeiroNome,
        telefone: telefoneFmt(body.user),
        bank_reference: j.bank_reference || null,
        executivo_email: executivoEmail,
        executivo_nome: executivo,
        canal: body?.agent?.channel || null,
        proximo_dia_util: h.proximo_dia_util || null,
        ultimo_contato: agoraSP(),
        // contexto_resumido é escrito depois, pelo node que roda após o
        // parse_output — aqui fica a 1a mensagem como rede de segurança
        contexto_resumido: String(body?.message?.text || "").slice(0, 300) || null,
      },

      // Aba "log" · Append Row · uma linha por mensagem, nunca deduplicada
      sheet_log: {
        timestamp: agoraSP(),
        sessao_id: sessaoId,
        tracker_id: body.tracker_id || null,
        telefone: body.user || null,
        direcao: "cliente",
        mensagem: String(body?.message?.text || "").slice(0, 500) || null,
      },

      _contexto_debug: {
        valor_bruto: j.monthly_payment ?? null,
        valor_parseado: valorNum,
        motivo_bloqueio_pagamento: podeFalarPagamento
          ? null
          : !programaAtivo
            ? `status_programa=${j.status_programa ?? "null"}`
            : "valor_ausente_ou_invalido",
      },
    },
  };
});
